reactiveclass Hub {
	statevars {
		Client clients[5];
		int count;
	}
	msgsrv initial() {
		count = 0;
	}
	msgsrv Register(Client ref) {
		if (count < 5) {
			clients[count] = ref;
			count = count + 1;
		}
	}
	msgsrv Ping() {
		sender.Pong();
	}
}

main {
	Hub hub();

	Client c1(hub):();
	Client c2(hub):();
